ton></th><th class='text-left' width="30%">矿机信息</th><th class='text-left nowrap' width="30%">矿机配置</th><th class='text-left nowrap' width="30%">其他配置</th><th></th></tr></thead><?php endif; ?><tbody><?php foreach($list as $key=>$vo): ?><tr data-dbclick><td class='list-table-check-td think-checkbox'><input class="list-check-box" value='<?php echo htmlentities($vo['id']); ?>' type='checkbox'></td><td class='list-table-sort-td'><input data-action-blur="<?php echo request()->url(); ?>" data-value="id#<?php echo htmlentities($vo['id']); ?>;action#sort;sort#{value}" data-loading="false" value="<?php echo htmlentities($vo['sort']); ?>" class="list-sort-input"></td><td class='text-left'><span style="width: 300px;overflow: hidden;white-space: nowrap;text-overflow: ellipsis;display: inline-block;"><?php echo htmlentities((isset($vo['title']) && ($vo['title'] !== '')?$vo['title']:'--')); ?></span><br>                添加时间：<?php echo htmlentities((isset($vo['time']) && ($vo['time'] !== '')?$vo['time']:'--')); ?><br>                使用期限：<?php echo htmlentities((isset($vo['day']) && ($vo['day'] !== '')?$vo['day']:'--')); ?><br></td><td class='text-left nowrap'>                保证金：<?php echo htmlentities((isset($vo['min']) && ($vo['min'] !== '')?$vo['min']:'--')); ?>元<br>                日总产出：<?php echo htmlentities((isset($vo['day_income']) && ($vo['day_income'] !== '')?$vo['day_income']:'--')); ?> BTC/天<br>                日运维费：<?php echo htmlentities((isset($vo['cost']) && ($vo['cost'] !== '')?$vo['cost']:'--')); ?> BTC/天<br></td><td class='text-left nowrap'>                算力：<?php echo htmlentities((isset($vo['power']) && ($vo['power'] !== '')?$vo['power']:'--')); ?>TH/s<br>                矿机总量：<?php echo htmlentities((isset($vo['total']) && ($vo['total'] !== '')?$vo['total']:'--')); ?>份<br>                剩余矿机：<?php echo htmlentities((isset($vo['stock']) && ($vo['stock'] !== '')?$vo['stock']:'--')); ?>份<br></td><td class='text-left'><div class="nowrap margin-bottom-5"><?php if(auth("akszadmin/mall/edit")): ?><a data-dbclick class="layui-btn layui-btn-sm" data-open='<?php echo url(ADMIN_MODULE."/mall/edit"); ?>?id=<?php echo htmlentities($vo['id']); ?>'>编 辑</a><?php else: ?><a data-tips-text="您没有编辑矿机的权限哦！" class="layui-btn layui-btn-sm layui-btn-primary layui-disabled">编 辑</a><?php endif; if(auth("akszadmin/mall/remove")): ?><a class="layui-btn layui-btn-sm layui-btn-danger" data-confirm="确定要删除数据吗?" data-action="<?php echo url(ADMIN_MODULE.'/mall/remove'); ?>" data-value="id#<?php echo htmlentities($vo['id']); ?>">删 除</a><?php else: ?><a data-tips-text="您没有删除矿机的权限哦！" class="layui-btn layui-btn-sm layui-btn-primary layui-disabled">删 除</a><?php endif; ?></div></td></tr><?php endforeach; ?></tbody></table><?php if(empty($list) || (($list instanceof \think\Collection || $list instanceof \think\Paginator ) && $list->isEmpty())): ?><span class="notdata">没有记录哦</span><?php else: ?><?php echo (isset($pagehtml) && ($pagehtml !== '')?$pagehtml:''); ?><?php endif; ?></div></div></div>